    nr: size,
    nq: size,
    np: size,
    A: DATA_TYPE[nr, nq, np] @ DRAM,
    C4: DATA_TYPE[np, np] @ DRAM,
    sum: DATA_TYPE[np] @ DRAM,
):
    assert nr > 0
    assert nq > 0
    assert np > 0

    # We compute, for each (r, q, p):
    #   A_new[r, q, p] = sum_{s=0..np-1} A_old[r, q, s] * C4[s, p]
    #
    # This is implemented as a matrix–vector product for each (r, q):
    #
    #   1) Zero the accumulation buffer sum[p] once per (r, q).
    #   2) For each s, read A[r, q, s] once and reuse it across all p.
    #      We traverse C4[s, p] row-wise (p innermost), which matches
    #      its row-major layout and gives unit-stride accesses.
    #   3) When the whole line is accumulated in sum[p], copy it
    #      back into A[r, q, p].
    #
    # Compared to the naive p-outer formulation, this:
    #   - reads each A[r, q, s] only once per (r, q),
    #   - walks C4[s, p] contiguously in p,
    #   - keeps sum[p] in a small, re-used buffer.

    # Tile the independent (r, q) space to improve cache reuse on A
    # and expose coarse-grain parallelism. We guard the boundary
    # tiles with explicit index checks instead of assuming divisibility.
    for Rb in seq(0, (nr + R_TILE - 1) / R_TILE):
        for Qb in seq(0, (nq + Q_TILE - 1) / Q_TILE):

            # Inside each (Rb, Qb) tile we iterate over the local
            # indices r_t and q_t, mapping them back to the global
            # coordinates r and q. Boundary checks ensure we do not
            # access out-of-bounds rows or columns.
            for r_t in seq(0, R_TILE):
                if Rb * R_TILE + r_t < nr:
                    for q_t in seq(0, Q_TILE):
                        if Qb * Q_TILE + q_t < nq:
                            r = Rb * R_TILE + r_t
                            q = Qb * Q_TILE + q_t

                            # 1) Initialize the accumulation buffer
                            #    for this (r, q) slice.
                            for p in seq(0, np):
                                sum[p] = 0.0

                            # 2) Accumulate contributions from all s.
                            #    We load A[r, q, s] once per s and reuse
                            #    it across all p, while streaming C4[s, :]
                            #    as a contiguous row.
                            for s in seq(0, np):
                                a_rqs: DATA_TYPE
                                a_rqs = A[r, q, s]
                                for p in seq(0, np):
                                    sum[p] += a_rqs * C4[s, p]

