from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # Imported for potential scheduling usage.
from exo.libs.memories import DRAM


@proc
def kernel_doitgen(
    nr: size,
    nq: size,
    np: size,
    A: DATA_TYPE[nr, nq, np] @ DRAM,
    C4: DATA_TYPE[np, np] @ DRAM,
    sum: DATA_TYPE[np] @ DRAM,
):
    # Basic sanity checks on sizes (these mirror the PolyBench configuration).
    assert nr > 0
    assert nq > 0
    assert np > 0

    # For each (r, q), compute a length-np row-vector A[r, q, :]
    # multiplied by the common np×np matrix C4, in-place.
    #
    # Mathematically:
    #   A_new[r, q, p] = Σ_{s=0..np-1} A_old[r, q, s] * C4[s, p]
    #
    # We realize this with an explicit accumulation buffer sum[p],
    # but we restructure the inner loops to improve locality:
    #
    #   1) Initialize sum[p] = 0 for all p once per (r, q).
    #   2) For each s, load A[r, q, s] once and reuse it across all p,
    #      accumulating into sum[p] while streaming a full row of C4[s, p].
    #   3) When the reduction is finished, copy sum[p] back into A[r, q, p].
    #
    # This is equivalent to the original Exo code but with a better
    # memory-access pattern for C4 and fewer redundant loads of A.

    for r in seq(0, nr):
        for q in seq(0, nq):

            # 1) Zero the accumulation buffer for this (r, q) once.
            for p in seq(0, np):
                sum[p] = 0.0

            # 2) Accumulate contributions from each source index s.
            #    We traverse s outer and p inner:
            #      - A[r, q, s] is read once per s.
            #      - C4[s, p] is read row-wise with p contiguous
            #        (ideal for cache and SIMD).
            for s in seq(0, np):
                a_rqs: DATA_TYPE
                a_rqs = A[r, q, s]

                for p in seq(0, np):
                    sum[p] += a_rqs * C4[s, p]

            # 3) Commit the accumulated result back into A.
            for p in seq(0, np):
                A[r, q, p] = sum[p]

EXO END
